 ICON.peDC=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${PE_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${PE_T(20,36,'battery wants: DC',{fs:24,fw:800,fill:BLU})}${PE_L(30,130,360,130,PE_AX,2)}${PE_L(30,80,360,80,BLU,6)}${PE_arrow(150,104,230,104,BLU,4)}${PE_T(195,154,'one way, steady',{fs:20,fw:700,a:'middle',fill:PE_MUT})}</g>`;
