 ICON.peRL=(x,y)=>{const vs=PE_pts(Math.sin,0,2*Math.PI,10,410,170,130),rl=PE_pts(PE_rl,0,2*Math.PI,10,410,170,130),xb=10+400*PE_BETA/(2*Math.PI),tail=PE_pts(PE_rl,Math.PI,PE_BETA,210,xb,170,130,60);return `<g transform="translate(${x-210} ${y-165})">${PE_L(10,170,410,170,PE_AX,2)}${PE_poly(vs,PE_AX,3,'stroke-dasharray="7 6"')}${PE_area(tail,170,RED,.25)}${PE_poly(rl,ORG,5)}${PE_T(xb+8,150,'β',{fs:30,fw:800,fill:ORG})}${PE_L(210,170,410,170,GRN,7)}${PE_T(410,330,'freewheeling: 0 V',{fs:24,fw:800,a:'end',fill:GRN})}</g>`};
 ICON.peFilt=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(10,320,410,320,PE_AX,2)}${PE_capPlot(10,410,320,30,0,325.27,GRN)}${PE_T(210,230,'C holds near the peak',{fs:26,fw:800,a:'middle',fill:GRN})}</g>`;
